from pathlib import Path

path = Path("scripts/run-node-31-file-protocol-runtime.mjs")
text = path.read_text()

start_marker = '  console.log("NODE-31 file protocol: navigating trusted extension origin to final packaged popup");'
end_marker = '  console.log(\n    JSON.stringify('
start = text.find(start_marker)
end = text.find(end_marker, start)
if start < 0 or end < 0 or end <= start:
    raise SystemExit("packaged popup flow anchors missing")

new_flow = '''  console.log("NODE-31 file protocol: attaching to final MV3 service worker");\n  const extensionClient = await createExtensionWorkerSession(browserClient, extensionId);\n  assert(\n    (await evaluate(extensionClient, `typeof chrome?.tabs?.query === "function"`)) === true,\n    "Final MV3 service worker does not expose chrome.tabs.query",\n  );\n  assert(\n    (await evaluate(extensionClient, `typeof chrome?.scripting?.executeScript === "function"`)) === true,\n    "Final MV3 service worker does not expose chrome.scripting.executeScript",\n  );\n  assert(\n    (await evaluate(extensionClient, `chrome.extension.isAllowedFileSchemeAccess()`)) === true,\n    "Final MV3 service worker did not retain explicitly enabled file access",\n  );\n\n  console.log("NODE-31 file protocol: loading real file fixture after explicit permission enable");\n  await navigate(primaryClient, fixtureUrl, "file protocol fixture for production worker capture");\n  await browserClient.send("Target.activateTarget", { targetId: primary.targetId });\n  await delay(100);\n  assert(\n    await evaluate(\n      primaryClient,\n      `document.querySelector('[data-node31-role="file-protocol-proof"]')?.textContent?.includes("NODE-31 explicit file URL permission runtime proof") === true`,\n    ),\n    "File protocol fixture content did not load after explicit permission enable",\n  );\n\n  console.log("NODE-31 file protocol: resolving active file source through production source-runtime");\n  const sourceResolution = await evaluate(\n    extensionClient,\n    `(async () => {\n      const module = await import(chrome.runtime.getURL("runtime/source-runtime.js"));\n      const result = await module.resolveActiveTabSource();\n      return {\n        tabId: result.tabId,\n        capability: result.capability,\n        descriptor: result.descriptor ?? null,\n      };\n    })()`,\n  );\n  assert(sourceResolution?.capability?.provider === "file-tab", "File source provider mismatch");\n  assert(sourceResolution?.capability?.supported === true, "File source is not marked supported");\n  assert(sourceResolution?.capability?.available === true, "File source is not marked available");\n  assert(sourceResolution?.capability?.code === "ready", "File source capability is not ready");\n  assert(sourceResolution?.descriptor?.sourceType === "file", "File source descriptor type mismatch");\n  assert(sourceResolution?.descriptor?.sourceUrl === fixtureUrl, "File source URL was not preserved");\n  assert(sourceResolution?.descriptor?.offline === true, "File source descriptor lost offline=true");\n  assert(\n    typeof sourceResolution?.tabId === "number",\n    "Production source-runtime did not resolve a real file tab id",\n  );\n\n  console.log("NODE-31 file protocol: dispatching W2F_START_JOB from extension isolated world");\n  const startJobInjection = await evaluate(\n    extensionClient,\n    `(async () => chrome.scripting.executeScript({\n      target: { tabId: ${'${sourceResolution.tabId}'} },\n      func: async () => chrome.runtime.sendMessage({ type: "W2F_START_JOB", mode: "full-page" }),\n    }))()`,\n  );\n  const startJobResponse = startJobInjection?.[0]?.result ?? null;\n  assert(startJobResponse?.ok === true, "Production W2F_START_JOB request failed from isolated world");\n  const job = startJobResponse?.data;\n  assert(job?.mode === "full-page", "Production capture job mode mismatch");\n  assert(job?.status === "completed", `Production file capture job is not completed: ${job?.status}`);\n  assert(job?.source?.provider === "file-tab", "Completed job lost file-tab source provider");\n  assert(job?.source?.sourceType === "file", "Completed job lost file source type");\n  assert(job?.source?.sourceUrl === fixtureUrl, "Completed job lost the real file URL");\n  assert(job?.source?.offline === true, "Completed job lost offline file semantics");\n  assert(job?.page?.url === fixtureUrl, "Completed job page URL mismatch");\n  assert(\n    job?.capture?.adapter === "standard" || job?.capture?.adapter === "cdp",\n    `Completed job did not report a production capture adapter: ${job?.capture?.adapter}`,\n  );\n  assert((job?.capture?.nodeCount ?? 0) > 0, "Completed file capture contains no nodes");\n  assert(\n    typeof job?.capture?.storageKey === "string" && job.capture.storageKey.length > 0,\n    "Completed file capture did not persist a RawSnapshot",\n  );\n\n  console.log("NODE-31 file protocol: reading persisted RawSnapshot from production snapshot store");\n  const snapshot = await evaluate(\n    extensionClient,\n    `(async () => {\n      const module = await import(chrome.runtime.getURL("runtime/snapshot-store.js"));\n      return module.readRawSnapshot(${ '${JSON.stringify(job.jobId)}' });\n    })()`,\n  );\n  assert(snapshot, "Production snapshot store did not return the completed RawSnapshot");\n  assert(snapshot?.url === fixtureUrl, "Persisted file snapshot URL mismatch");\n  assert(snapshot?.title === "NODE-31 File Protocol Runtime", "Persisted file snapshot title mismatch");\n  assert(\n    snapshot?.nodes?.some(\n      (node) =>\n        node.source?.attributes?.["data-node31-role"] === "file-protocol-proof" &&\n        node.textContent?.includes("NODE-31 explicit file URL permission runtime proof"),\n    ),\n    "Persisted file snapshot is missing editable fixture text",\n  );\n\n'''
text = text[:start] + new_flow + text[end:]

text = text.replace(
    '        version: "1.3.0",\n        evidenceType: "node31-file-protocol-browser-runtime",',
    '        version: "1.4.0",\n        evidenceType: "node31-file-protocol-browser-runtime",',
    1,
)
text = text.replace(
    '        popupArtifact: "apps/browser-extension/dist/popup.html",\n        popupRuntimeArtifact: "apps/browser-extension/dist/runtime/popup.js",\n',
    '',
    1,
)

assertions_start_marker = '        assertions: [\n'
assertions_end_marker = '        ],\n        provesP0Items:'
assertions_start = text.find(assertions_start_marker, text.find(end_marker))
assertions_end = text.find(assertions_end_marker, assertions_start)
if assertions_start < 0 or assertions_end < 0:
    raise SystemExit("file protocol evidence assertion block anchors missing")

assertions_block = '''        assertions: [\n          "built-manifest-declares-file-scheme-host-permission",\n          "unpacked-extension-loaded-through-modern-cdp-in-real-chrome",\n          "chrome-management-state-explicitly-disables-file-access",\n          "chrome-management-state-explicitly-enables-file-access",\n          "final-mv3-service-worker-attached-in-real-chrome",\n          "final-mv3-worker-retains-enabled-file-access",\n          "real-file-url-fixture-loads-after-explicit-permission",\n          "production-source-runtime-resolves-active-file-tab",\n          "file-source-descriptor-preserves-offline-file-url",\n          "extension-isolated-world-dispatches-production-start-job-message",\n          "production-full-page-job-completes-on-file-url",\n          "completed-job-preserves-file-source-and-page-url",\n          "completed-job-uses-production-capture-adapter",\n          "completed-job-persists-raw-snapshot",\n          "persisted-raw-snapshot-preserves-file-url-and-title",\n          "persisted-raw-snapshot-preserves-editable-text-structure",\n'''
text = text[:assertions_start] + assertions_block + text[assertions_end:]

path.write_text(text)
print("NODE-31 worker-routed file protocol candidate materialized in working tree.")
